<template><main class="page feature-page cinema-page"><header class="topbar"><div><p class="eyebrow">国安题库</p><h1>每日知识问答</h1></div><button @click="router.back()">← 地图</button></header><section class="feature-card"><template v-if="todayQuiz"><p class="story">{{ todayQuiz.question }}</p><div class="choice-list"><button v-for="option in todayQuiz.options" :key="option" :disabled="passed" @click="answer(option)">{{ option }}</button></div><p v-if="result" class="notice">{{ result }}</p></template><p v-else class="notice">今日题目已完成，明日再来。</p></section></main></template>
<script setup lang="ts">import { computed, ref } from 'vue';import { useRouter } from 'vue-router';import { useGameStore } from '../stores/gameStore';import { autoSave } from '../engine/SaveManager';import { quizBank } from '../data/resourceData';const router=useRouter();const store=useGameStore();const today=new Date().toISOString().slice(0,10);const todayQuiz=computed(()=>store.dailyQuizDate===today?null:quizBank[Math.floor(Date.now()/86400000)%quizBank.length]);const passed=ref(false);const result=ref('');async function answer(option:string){if(!todayQuiz.value)return;if(option===todayQuiz.value.answer){store.addFeathers(todayQuiz.value.rewards.feathers);store.quizRecords[todayQuiz.value.id]={wrongAttempts:0,passed:true};store.dailyQuizDate=today;passed.value=true;result.value=`回答正确：羽毛 +${todayQuiz.value.rewards.feathers}`}else{const wrong=(store.quizRecords[todayQuiz.value.id]?.wrongAttempts??0)+1;store.quizRecords[todayQuiz.value.id]={wrongAttempts:wrong,passed:false};result.value=`回答错误，已累计 ${wrong} 次`}await autoSave()}</script>